const saoPauloEmbed='https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d467688.89495119266!2d-46.5952992!3d-23.6824124!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x94ce448183a461d1%3A0x9ba94b08ff335bae!2zU8OjbyBQYXVsbywgU1A!5e0!3m2!1spt-BR!2sbr!4v1793735717305!5m2!1spt-BR!2sbr';
const mapSection=document.createElement('section');mapSection.id='mapa';mapSection.className='map-section';
mapSection.innerHTML='<div class="section-head"><div><p class="eyebrow" id="map-eyebrow"></p><h2 id="map-title"></h2></div><p id="map-intro"></p></div><div class="map-layout"><div class="map-places"><label for="map-location" id="map-location-label"></label><select id="map-location"></select><p class="eyebrow" id="map-category"></p><h3 id="map-place-title"></h3><p id="map-place-area"></p><div class="map-actions"><a id="map-open" class="button" target="_blank" rel="noopener noreferrer"></a><a id="map-directions" class="secondary-button" target="_blank" rel="noopener noreferrer"></a></div><p class="note" id="map-accuracy"></p></div><div><div id="map-canvas" class="map-canvas"><div id="map-placeholder"><span aria-hidden="true" class="map-symbol">⌖</span><p id="map-privacy"></p><button id="map-load" class="button"></button></div></div><p class="note" id="map-caption"></p></div></div>';
$('#postal').before(mapSection);
const mapNav=document.createElement('a');mapNav.href='#mapa';document.querySelector('header nav').append(mapNav);
const storyMap=document.createElement('a');storyMap.className='secondary-button';storyMap.target='_blank';storyMap.rel='noopener noreferrer';const storyActions=document.createElement('div');storyActions.className='story-actions';$('#story-add').before(storyActions);storyActions.append($('#story-add'),storyMap);
function mapSearchUrl(query){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query)}
function mapDirectionsUrl(query){return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(query)}
function refreshMapSelection(){const p=places.find(p=>p.id===$('#map-location').value);const query=p?mapQueries[p.id]:'São Paulo SP Brasil';$('#map-category').textContent=p?t(p.category):t('Visão geral da cidade');$('#map-place-title').textContent=p?t(p.title):'São Paulo';$('#map-place-area').textContent=p?t(p.area):t('São Paulo · Brasil');$('#map-open').href=mapSearchUrl(query);$('#map-directions').href=mapDirectionsUrl(query)}
function renderMap(){const selected=$('#map-location').value;const all=document.createElement('option');all.value='city';all.textContent=t('São Paulo · visão geral');const groups=['Sabores','Arte de Rua','Respiros','Cidade & Memória'].map(category=>{const group=document.createElement('optgroup');group.label=t(category);for(const p of places.filter(p=>p.category===category)){const option=document.createElement('option');option.value=p.id;option.textContent=t(p.title);group.append(option)}return group});$('#map-location').replaceChildren(all,...groups);$('#map-location').value=selected==='city'||PLACE_IDS.includes(selected)?selected:'city';
for(const [id,text] of Object.entries({'map-eyebrow':'Onde as camadas se encontram','map-title':'São Paulo no mapa','map-intro':'Uma cidade no Sudeste do Brasil, no estado de São Paulo. Explore a cidade e encontre os cenários das histórias.','map-location-label':'Escolha uma localidade','map-open':'Abrir no Google Maps ↗','map-directions':'Como chegar ↗','map-accuracy':'Algumas histórias representam um bairro ou uma região, sem um endereço único. Confira o resultado e as condições de visita no Google Maps.','map-privacy':'O mapa é fornecido pelo Google e será carregado ao clicar.','map-load':'Carregar mapa de São Paulo','map-caption':'Mapa de São Paulo. Para ver o local escolhido, use os links ao lado.'})){const node=document.getElementById(id);if(node)node.textContent=t(text)}
mapNav.textContent=t('Mapa');storyMap.textContent=t('Localização da história ↗');const iframe=$('#map-canvas iframe');if(iframe)iframe.title=t('Mapa de São Paulo fornecido pelo Google');refreshMapSelection()}
$('#map-location').onchange=refreshMapSelection;
$('#map-load').onclick=()=>{const iframe=document.createElement('iframe');iframe.title=t('Mapa de São Paulo fornecido pelo Google');iframe.src=saoPauloEmbed;iframe.loading='lazy';iframe.referrerPolicy='no-referrer';iframe.allowFullscreen=true;$('#map-canvas').replaceChildren(iframe)};
$('#cards').addEventListener('click',event=>{const id=event.target.closest('[data-story]')?.dataset.story;if(!PLACE_IDS.includes(id))return;storyMap.href=mapSearchUrl(mapQueries[id]);$('#map-location').value=id;refreshMapSelection()});
const renderFeaturesBeforeMap=renderFeatures;renderFeatures=function(){renderFeaturesBeforeMap();renderMap()};renderMap();
